<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Descontos';$products=$pdo->query('SELECT id,nome FROM produtos WHERE ativo=1 ORDER BY nome')->fetchAll();$cats=$pdo->query('SELECT id,nome FROM categorias WHERE ativo=1 ORDER BY nome')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action'];$id=(int)($_POST['id']??0);if($action==='toggle'){$pdo->prepare('UPDATE descontos SET ativo=CASE ativo WHEN 1 THEN 0 ELSE 1 END WHERE id=?')->execute([$id]);flash('success','Status do desconto atualizado.');redirect('descontos.php');}if($action==='save'){$nome=trim($_POST['nome']);$tipo=$_POST['tipo'];$valor=number_value($_POST['valor']);$pid=(int)$_POST['produto_id']?:null;$cid=(int)$_POST['categoria_id']?:null;if($nome&&$valor>=0){$pdo->prepare('INSERT INTO descontos(nome,tipo,valor,produto_id,categoria_id,ativo,criado_em) VALUES(?,?,?,?,?,?,?)')->execute([$nome,$tipo,$valor,$pid,$cid,1,now()]);log_action('desconto');flash('success','Regra de desconto cadastrada.');redirect('descontos.php');}}}$rows=$pdo->query('SELECT d.*,p.nome produto_nome,c.nome categoria_nome FROM descontos d LEFT JOIN produtos p ON p.id=d.produto_id LEFT JOIN categorias c ON c.id=d.categoria_id ORDER BY d.ativo DESC,d.nome')->fetchAll();include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Descontos configuráveis</h1><a class="btn secondary" href="index.php">Configurações</a></div><div class="grid grid-2"><div class="card"><h3>Nova regra</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><div class="field"><label>Nome</label><input name="nome" required></div><div class="field"><label>Tipo</label><select name="tipo"><option value="percentual">Percentual</option><option value="fixo">Valor fixo</option><option value="produto">Por produto</option><option value="categoria">Por categoria</option></select></div><div class="field"><label>Valor</label><input name="valor" type="number" step="0.01" min="0" required></div><div class="field"><label>Produto relacionado</label><select name="produto_id"><option value="0">Nenhum</option><?php foreach($products as $p): ?><option value="<?=$p['id']?>"><?=e($p['nome'])?></option><?php endforeach;?></select></div><div class="field"><label>Categoria relacionada</label><select name="categoria_id"><option value="0">Nenhuma</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>"><?=e($c['nome'])?></option><?php endforeach;?></select></div><button class="btn primary" style="margin-top:10px">Cadastrar regra</button></form></div><div class="card"><h3>Regras</h3><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Tipo</th><th>Valor</th><th>Vínculo</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['nome'])?></td><td><?=e($r['tipo'])?></td><td><?=e($r['valor'])?></td><td><?=e($r['produto_nome']?:$r['categoria_nome']?:'Geral')?></td><td><?=status_badge($r['ativo']?'Ativo':'Inativo')?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small secondary">Alternar</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
